import java.nio.file.*;import java.util.*;import java.util.zip.*;import java.io.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class AuditAffinityLinkage {
 static Map<String,ClassNode> classes=new HashMap<>();static Set<String> errors=new TreeSet<>();
 static boolean internal(String s){return s.startsWith("school/magiccodex/")||s.startsWith("kr/chacademy/npc/");}
 static void require(String c,String context){if(c.startsWith("[")){type(Type.getType(c),context);return;}if(internal(c)&&!classes.containsKey(c))errors.add(context+" missing class "+c);}
 static void type(Type t,String c){if(t.getSort()==Type.OBJECT)require(t.getInternalName(),c);else if(t.getSort()==Type.ARRAY)type(t.getElementType(),c);else if(t.getSort()==Type.METHOD){for(Type a:t.getArgumentTypes())type(a,c);type(t.getReturnType(),c);}}
 static boolean externalMember(String owner,String name,String desc,boolean method){if(owner.startsWith("java/")){try{Class<?> c=Class.forName(owner.replace('/' ,'.'),false,ClassLoader.getPlatformClassLoader());if(method){for(var m:c.getMethods())if(m.getName().equals(name)&&Type.getMethodDescriptor(m).equals(desc))return true;}else{for(var f:c.getFields())if(f.getName().equals(name)&&Type.getDescriptor(f.getType()).equals(desc))return true;}return false;}catch(Exception e){return false;}}return owner.equals("org/bukkit/event/Listener")?false:owner.equals("org/bukkit/plugin/messaging/PluginMessageListener")?method&&name.equals("onPluginMessageReceived"):!internal(owner);}
 static boolean member(String owner,String name,String desc,boolean method,Set<String> seen){if(!seen.add(owner))return false;ClassNode c=classes.get(owner);if(c==null)return externalMember(owner,name,desc,method);if(method&&c.methods.stream().anyMatch(x->x.name.equals(name)&&x.desc.equals(desc)))return true;if(!method&&c.fields.stream().anyMatch(x->x.name.equals(name)&&x.desc.equals(desc)))return true;if(name.equals("<init>"))return false;if(c.superName!=null&&member(c.superName,name,desc,method,seen))return true;for(String i:c.interfaces)if(member(i,name,desc,method,seen))return true;return false;}
 public static void main(String[] args)throws Exception{
  try(ZipFile z=new ZipFile(args[0])){for(var it=z.entries();it.hasMoreElements();){var e=it.nextElement();if(e.getName().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(z.getInputStream(e).readAllBytes()).accept(c,0);classes.put(c.name,c);}}}
  for(int i=1;i<args.length;i++)try(ZipFile z=new ZipFile(args[i])){for(var it=z.entries();it.hasMoreElements();){var e=it.nextElement();if(e.getName().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(z.getInputStream(e).readAllBytes()).accept(c,0);classes.putIfAbsent(c.name,c);}}}
  try(ZipFile base=new ZipFile(args[args.length-1]);ZipFile target=new ZipFile(args[0])){
   for(var it=target.entries();it.hasMoreElements();){var e=it.nextElement();if(!e.getName().endsWith(".class"))continue;var before=base.getEntry(e.getName());byte[] b=target.getInputStream(e).readAllBytes();if(before!=null&&Arrays.equals(b,base.getInputStream(before).readAllBytes()))continue;ClassNode c=classes.get(e.getName().substring(0,e.getName().length()-6));if(c==null)continue;String where=c.name;
    if(c.superName!=null)require(c.superName,where);for(String v:c.interfaces)require(v,where);for(FieldNode f:c.fields)type(Type.getType(f.desc),where);for(MethodNode m:c.methods){type(Type.getMethodType(m.desc),where);for(var ins:m.instructions){
     if(ins instanceof TypeInsnNode t)require(t.desc,where);
     if(ins instanceof MethodInsnNode v){require(v.owner,where);type(Type.getMethodType(v.desc),where);if(internal(v.owner)&&classes.containsKey(v.owner)&&!member(v.owner,v.name,v.desc,true,new HashSet<>()))errors.add(where+" missing method "+v.owner+"."+v.name+v.desc);}
     if(ins instanceof FieldInsnNode v){require(v.owner,where);type(Type.getType(v.desc),where);if(internal(v.owner)&&classes.containsKey(v.owner)&&!member(v.owner,v.name,v.desc,false,new HashSet<>()))errors.add(where+" missing field "+v.owner+"."+v.name);}
     if(ins instanceof InvokeDynamicInsnNode v){type(Type.getMethodType(v.desc),where);for(Object a:v.bsmArgs)if(a instanceof Type t)type(t,where);else if(a instanceof Handle h){require(h.getOwner(),where);}}
    }}
   }
  }
  Set<String> modified=new HashSet<>();try(ZipFile base=new ZipFile(args[args.length-1]);ZipFile target=new ZipFile(args[0])){for(var it=target.entries();it.hasMoreElements();){var e=it.nextElement();if(!e.getName().endsWith(".class"))continue;var old=base.getEntry(e.getName());if(old==null||!Arrays.equals(target.getInputStream(e).readAllBytes(),base.getInputStream(old).readAllBytes()))modified.add(e.getName().substring(0,e.getName().length()-6));}}
  // Unchanged callers must also remain compatible with each replaced API class.
  for(ClassNode c:classes.values())for(MethodNode m:c.methods)for(var ins:m.instructions){if(ins instanceof MethodInsnNode v&&modified.contains(v.owner)&&!member(v.owner,v.name,v.desc,true,new HashSet<>()))errors.add(c.name+" unchanged/replaced caller missing method "+v.owner+"."+v.name+v.desc);if(ins instanceof FieldInsnNode v&&modified.contains(v.owner)&&!member(v.owner,v.name,v.desc,false,new HashSet<>()))errors.add(c.name+" unchanged/replaced caller missing field "+v.owner+"."+v.name);}
  for(String e:errors)System.out.println(e);if(!errors.isEmpty())System.exit(2);System.out.println("PASS changed-class and unchanged-caller internal dependency/member linkage");
 }
}
